<template><div><DsPageHeader title="Pacotes" subtitle="Organização dos modelos de laudo por pacote" icon="box-seam"/><DsPageShell><div class="flex justify-end mb-4"><DsButton v-if="auth.isAdmin" variant="success" @click="open()">Novo pacote</DsButton></div><DsAlert v-if="error" variant="error">{{error}}</DsAlert><DsTable v-else><template #head><tr><th>Código</th><th>Nome</th><th>Descrição</th><th>Scripts</th><th/></tr></template><tr v-for="p in pacotes" :key="p.codPacote"><td>{{p.codPacote}}</td><td>{{p.nome}}</td><td>{{p.descricao||'-'}}</td><td>{{p.quantidadeScripts}}</td><td><div v-if="auth.isAdmin" class="flex justify-end gap-2"><DsButton size="sm" variant="secondary" @click="open(p)">Editar</DsButton><DsButton size="sm" variant="danger" @click="remove(p)">Excluir</DsButton></div></td></tr></DsTable></DsPageShell><DsModal v-model="modal" :title="editing?'Editar pacote':'Novo pacote'" size="lg"><div class="space-y-3"><DsInput v-model="form.nome" label="Nome"/><DsTextarea v-model="form.descricao" label="Descrição"/><div><p class="text-sm font-medium mb-2">Scripts no pacote</p><div class="max-h-64 overflow-auto border rounded-2xl p-3 space-y-2"><label v-for="s in scripts" :key="s.codScriptLaudo" class="flex gap-2 text-sm"><input v-model="selected" type="checkbox" :value="s.codScriptLaudo"/>{{s.nome}}</label></div></div></div><template #footer><DsButton variant="secondary" @click="modal=false">Cancelar</DsButton><DsButton @click="save">Salvar</DsButton></template></DsModal></div></template>
<script setup lang="ts">definePageMeta({layout:'default'});const api=useApi(),auth=useAuthStore(),swal=useSwal();const pacotes=ref<any[]>([]),scripts=ref<any[]>([]),selected=ref<number[]>([]),error=ref(''),modal=ref(false),editing=ref<any>(null),form=reactive({nome:'',descricao:''});async function load(){try{const[p,s]=await Promise.all([api.get<any>('/api/web/cadastros/pacotes'),api.get<any>('/api/web/cadastros/pacotes/scripts')]);pacotes.value=p.data||[];scripts.value=s.data||[]}catch(e){error.value=e instanceof Error?e.message:'Erro ao carregar.'}}function open(p?:any){editing.value=p||null;form.nome=p?.nome||'';form.descricao=p?.descricao||'';selected.value=p?scripts.value.filter(s=>s.codPacote===p.codPacote).map(s=>s.codScriptLaudo):[];modal.value=true}async function save(){try{const body={...form,codigosScripts:selected.value};editing.value?await api.put(`/api/web/cadastros/pacotes/${editing.value.codPacote}`,body):await api.post('/api/web/cadastros/pacotes',body);modal.value=false;await load();await swal.toast('Pacote salvo.')}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao salvar.','error')}}async function remove(p:any){const c=await swal.confirm('Excluir pacote',`Os scripts serão desvinculados de "${p.nome}". Continuar?`);if(!c?.isConfirmed)return;try{await api.del(`/api/web/cadastros/pacotes/${p.codPacote}`);await load()}catch(e){await swal.toast(e instanceof Error?e.message:'Erro ao excluir.','error')}}onMounted(load)</script>
